// 1. If _this_ is not an Object, then
//   1. Throw a *TypeError* exception.
assert.throws(TypeError, () => set.call(undefined, ''));
assert.throws(TypeError, () => set.call(null, ''));
assert.throws(TypeError, () => set.call(true, ''));

